const { Client } = require('pg');
const axios = require('axios');

const DATABASE_URL = process.env.DATABASE_URL;
const ANTHROPIC_API_KEY = process.env.ANTHROPIC_API_KEY;
const STRIPE_SECRET_KEY = process.env.STRIPE_SECRET_KEY;

async function checkDatabase() {
    const client = new Client({ connectionString: DATABASE_URL });
    try {
        await client.connect();
        console.log('Database connection successful.');
    } catch (error) {
        console.error('Database connection failed:', error.message);
    } finally {
        await client.end();
    }
}

async function checkAnthropicAPI() {
    try {
        const response = await axios.get('https://api.anthropic.com/v1/health', {
            headers: { 'Authorization': `Bearer ${ANTHROPIC_API_KEY}` }
        });
        console.log('Anthropic API response:', response.data);
    } catch (error) {
        console.error('Anthropic API check failed:', error.message);
    }
}

async function checkStripeAPI() {
    try {
        const response = await axios.get('https://api.stripe.com/v1/charges', {
            headers: { 'Authorization': `Bearer ${STRIPE_SECRET_KEY}` }
        });
        console.log('Stripe API response:', response.data);
    } catch (error) {
        console.error('Stripe API check failed:', error.message);
    }
}

async function runChecks() {
    await checkDatabase();
    await checkAnthropicAPI();
    await checkStripeAPI();
}

runChecks();

